//! The advance widths of the twelve Latin standard 14 fonts in thousandths of an em, by
//! character, sorted: generated by `tools/standard14/generate.py` from the pinned PDFium
//! (chromium/7881), whose standard fonts match Adobe's Core14 AFM metrics. Do not edit;
//! rerun the script (THIRD_PARTY_NOTICES.md, docs/DEPENDENCIES.md).

/// Each font's `/BaseFont` and its widths.
static FONTS: [(&str, &[(char, u16)]); 12] = [
    ("Courier", &COURIER),
    ("Courier-Bold", &COURIER),
    ("Courier-Oblique", &COURIER),
    ("Courier-BoldOblique", &COURIER),
    ("Helvetica", &HELVETICA),
    ("Helvetica-Bold", &HELVETICA_BOLD),
    ("Helvetica-Oblique", &HELVETICA_OBLIQUE),
    ("Helvetica-BoldOblique", &HELVETICA_BOLDOBLIQUE),
    ("Times-Roman", &TIMES_ROMAN),
    ("Times-Bold", &TIMES_BOLD),
    ("Times-Italic", &TIMES_ITALIC),
    ("Times-BoldItalic", &TIMES_BOLDITALIC),
];

/// The widths of the standard 14 font `base_font` names, a subset tag before the name or not.
pub(crate) fn widths(base_font: Option<&str>) -> Option<&'static [(char, u16)]> {
    let name = base_font?;
    let name = name.split_once('+').map_or(name, |(_, name)| name);
    FONTS
        .iter()
        .find(|(font, _)| *font == name)
        .map(|(_, widths)| *widths)
}

/// The width of `c` in `widths`, in thousandths of an em.
pub(crate) fn width(widths: &[(char, u16)], c: char) -> Option<f32> {
    let at = widths.binary_search_by_key(&c, |&(c, _)| c).ok()?;
    widths.get(at).map(|&(_, width)| f32::from(width))
}

